DROP PROCEDURE IF EXISTS `ms_aq40_cache_restore_20261007`;
DELIMITER $$
CREATE PROCEDURE `ms_aq40_cache_restore_20261007`()
BEGIN
    DECLARE `normal_aq40` INT UNSIGNED DEFAULT 0;
    DECLARE `heroic_aq40` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_aq40` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_aq20` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_21_30` INT UNSIGNED DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    IF (SELECT COUNT(*) FROM `information_schema`.`TABLES`
        WHERE `TABLE_SCHEMA` = DATABASE() AND `TABLE_NAME` IN ('item_loot_template', 'reference_loot_template')
            AND `ENGINE` = 'InnoDB') <> 2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: InnoDB loot tables required';
    END IF;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM `tmp_ms_aq40_candidate`) <> 6651 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: expected 6651 candidate assignments';
    END IF;
    -- One scan: MySQL cannot reopen a temporary table twice in one statement.
    SELECT COUNT(CASE WHEN `Pool` = 9003601 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003602 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003603 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003604 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003605 THEN 1 END)
    INTO `normal_aq40`, `heroic_aq40`, `mythic_aq40`,
        `mythic_aq20`, `dungeon_21_30`
    FROM `tmp_ms_aq40_candidate`;
    IF `normal_aq40` <> 139 OR `heroic_aq40` <> 119 OR `mythic_aq40` <> 139
        OR `mythic_aq20` <> 144 OR `dungeon_21_30` <> 6110 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: candidate family count mismatch';
    END IF;
    IF (SELECT COUNT(*) FROM `item_template`
        WHERE `entry` IN (1278075, 1278077, 1278078) AND (`Flags` & 4) <> 0 AND `ScriptName` = '') <> 3 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: missing scriptless HAS_LOOT containers';
    END IF;
    IF EXISTS (
        SELECT 1 FROM `tmp_ms_aq40_candidate` AS `c`
        LEFT JOIN `item_template` AS `i` ON `i`.`entry` = `c`.`Item`
        WHERE `i`.`entry` IS NULL
            OR `i`.`class` <> `c`.`Class` OR `i`.`subclass` <> `c`.`Subclass`
            OR `i`.`InventoryType` <> `c`.`InventoryType` OR `i`.`Quality` <> `c`.`Quality`
            OR `i`.`RequiredLevel` <> `c`.`RequiredLevel` OR `i`.`displayid` <> `c`.`DisplayId`
            OR `i`.`ItemLevel` <> `c`.`ItemLevel`
            OR (`c`.`Description` LIKE '@%' AND BINARY `i`.`description` <> BINARY `c`.`Description`)
            OR `i`.`RequiredLevel` > 60 OR `i`.`class` NOT IN (2, 4) OR `i`.`InventoryType` = 0
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: candidate metadata mismatch';
    END IF;
    IF EXISTS (SELECT 1 FROM `reference_loot_template`
        WHERE `Entry` IN (9003601, 9003602, 9003603, 9003604, 9003605)
            AND `Comment` <> 'MS Classic AQ40 cache family pool')
        OR EXISTS (SELECT 1 FROM `reference_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `item_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605)
                AND `Entry` NOT IN (1278075, 1278077, 1278078)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: reserved reference namespace collision';
    END IF;
    IF EXISTS (SELECT 1 FROM `creature_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `disenchant_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `fishing_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `gameobject_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `mail_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `milling_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `pickpocketing_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `prospecting_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `skinning_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `spell_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605))
        OR EXISTS (SELECT 1 FROM `player_loot_template`
            WHERE ABS(`Reference`) IN (9003601, 9003602, 9003603, 9003604, 9003605)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: references used by another loot store';
    END IF;
    IF EXISTS (SELECT 1 FROM `conditions`
        WHERE (`SourceTypeOrReferenceId` = 10
            AND `SourceGroup` IN (9003601,9003602,9003603,9003604,9003605))
            OR (`SourceTypeOrReferenceId` = 5 AND `SourceGroup` IN (1278075,1278077,1278078))) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: existing loot conditions require review';
    END IF;
    DELETE FROM `reference_loot_template`
    WHERE `Entry` IN (9003601, 9003602, 9003603, 9003604, 9003605);
    INSERT INTO `reference_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    SELECT `Pool`, `Item`, 0, 0, 0, 1, 1, 1, 1, 'MS Classic AQ40 cache family pool'
    FROM `tmp_ms_aq40_candidate`;
    DELETE FROM `item_loot_template` WHERE `Entry` IN (1278075, 1278077, 1278078);
    INSERT INTO `item_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    VALUES
    (1278075, 1, 9003601, 100, 0, 1, 1, 1, 1, 'MS AQ40: guaranteed Normal AQ40'),
    (1278075, 2, 9003604, 100, 0, 1, 2, 1, 1, 'MS AQ40: guaranteed Mythic AQ20'),
    (1278075, 3, 9003605, 10, 0, 1, 3, 1, 1, 'MS AQ40: optional Mythic 21-30 Dungeon'),
    (1278077, 1, 9003601, 100, 0, 1, 1, 1, 1, 'MS AQ40: guaranteed Normal AQ40'),
    (1278077, 2, 9003601, 50, 0, 1, 2, 1, 1, 'MS AQ40: optional second Normal AQ40'),
    (1278077, 3, 9003602, 10, 0, 1, 3, 1, 1, 'MS AQ40: optional Heroic AQ40'),
    (1278077, 4, 9003605, 10, 0, 1, 4, 1, 1, 'MS AQ40: optional Mythic 21-30 Dungeon'),
    (1278078, 1, 9003602, 100, 0, 1, 1, 1, 1, 'MS AQ40: guaranteed Heroic AQ40'),
    (1278078, 2, 9003603, 10, 0, 1, 2, 1, 1, 'MS AQ40: optional Mythic AQ40'),
    (1278078, 3, 9003605, 10, 0, 1, 3, 1, 1, 'MS AQ40: optional Mythic 21-30 Dungeon');
    IF (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278075) <> 3
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278077) <> 4
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278078) <> 3
        OR (SELECT COUNT(*) FROM `reference_loot_template`
            WHERE `Entry` IN (9003601,9003602,9003603,9003604,9003605)) <> 6651 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ40 caches: post-write row count mismatch';
    END IF;
    COMMIT;
END$$
DELIMITER ;
CALL `ms_aq40_cache_restore_20261007`();
DROP PROCEDURE `ms_aq40_cache_restore_20261007`;

SELECT `Entry`, `Reference`, `Chance`, `GroupId`, `MinCount`, `MaxCount`
FROM `item_loot_template` WHERE `Entry` IN (1278075,1278077,1278078) ORDER BY `Entry`, `Item`;
SELECT `Entry`, COUNT(*) AS `Candidates`
FROM `reference_loot_template`
    WHERE `Entry` IN (9003601,9003602,9003603,9003604,9003605)
GROUP BY `Entry`;
DROP TEMPORARY TABLE `tmp_ms_aq40_candidate`;
